#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Hạ tầng cho dự án ecommerce: GitHub repo + Environments, SSH deploy vào VPS,
# DNS Cloudflare, Cloudflare R2, Sentry, secret sinh tự động, khóa mã hóa backup.
#
# Chạy từ gốc repo:  bash scripts/setup-infra.sh
# Chạy lại được: giá trị không bí mật được nhớ trong .env.infra (gitignored).
#
# Hợp đồng tên với CI (ticket 15 phải dùng đúng các tên này):
#   Repo secrets:   DEPLOY_SSH_KEY, SENTRY_AUTH_TOKEN
#   Repo variables: DEPLOY_HOST, DEPLOY_USER, DEPLOY_KNOWN_HOSTS,
#                   SENTRY_ORG, SENTRY_PROJECT_API, SENTRY_PROJECT_WEB,
#                   SENTRY_DSN_API, SENTRY_DSN_WEB, R2_ACCOUNT_ID
#   Environment "staging" và "production", mỗi cái có:
#     secrets:   POSTGRES_PASSWORD, JWT_CUSTOMER_SECRET, JWT_STAFF_SECRET,
#                R2_ACCESS_KEY_ID, R2_SECRET_ACCESS_KEY
#     variables: PUBLIC_DOMAIN, R2_PUBLIC_BUCKET, R2_PRIVATE_BUCKET, R2_PUBLIC_URL
#   Chỉ "production" có thêm:
#     secrets:   BACKUP_R2_ACCESS_KEY_ID, BACKUP_R2_SECRET_ACCESS_KEY
#     variables: BACKUP_R2_BUCKET, BACKUP_AGE_RECIPIENT

# set_env_secret ENV NAME VALUE / set_env_var ENV NAME VALUE: như set_secret /
# set_var nhưng ghi vào một GitHub Environment.
set_env_secret() {
  local env="$1" name="$2" value="$3"
  if printf '%s' "$value" | gh secret set "$name" --env "$env" >/dev/null 2>&1; then
    WRITTEN_SECRET+=("$env/$name")
    printf '  %s✓ set%s secret %s (env %s)\n' "$GREEN" "$RESET" "$name" "$env"
  else
    SKIPPED+=("secret $name trong environment $env (gh secret set $name --env $env)")
    warn "không ghi được secret $name vào env $env; làm tay sau"
  fi
}

set_env_var() {
  local env="$1" name="$2" value="$3"
  if gh variable set "$name" --env "$env" --body "$value" >/dev/null 2>&1; then
    printf '  %s✓ set%s variable %s (env %s)\n' "$GREEN" "$RESET" "$name" "$env"
  else
    SKIPPED+=("variable $name trong environment $env")
    warn "không ghi được variable $name vào env $env; làm tay sau"
  fi
}

R2_DASH="https://dash.cloudflare.com/?to=/:account/r2/overview"
DEPLOY_KEY="$HOME/.ssh/ecommerce_deploy"
# Chạy trên VPS: đọc public key từ stdin, thêm vào authorized_keys nếu chưa có.
# shellcheck disable=SC2016  # biến được mở rộng ở phía VPS, không phải ở máy này
ADD_KEY_REMOTE='umask 077; mkdir -p ~/.ssh; key=$(cat); grep -qxF "$key" ~/.ssh/authorized_keys 2>/dev/null || printf "%s\n" "$key" >> ~/.ssh/authorized_keys'

run_wizard() {

TOTAL_STAGES=13
ENV_FILE=".env.infra"

banner "Thiết lập hạ tầng ecommerce"

# ── 1 ────────────────────────────────────────────────────────────────────
stage "Kiểm tra công cụ"
local missing=() c
for c in git gh ssh ssh-keygen ssh-keyscan openssl; do
  command -v "$c" >/dev/null 2>&1 || missing+=("$c")
done
if (( ${#missing[@]} )); then
  warn "thiếu công cụ: ${missing[*]}. Cài rồi chạy lại."
  exit 1
fi
command -v age-keygen >/dev/null 2>&1 \
  || warn "chưa có age-keygen (bước 13 sẽ bị bỏ qua). Cài: winget install FiloSottile.age"
if ! gh auth status >/dev/null 2>&1; then
  say "Đăng nhập GitHub CLI trước:"
  step "Chạy: gh auth login   (chọn GitHub.com → HTTPS → Login with a web browser)"
  pause "Đăng nhập xong thì Enter"
  gh auth status >/dev/null 2>&1 || { warn "gh vẫn chưa đăng nhập"; exit 1; }
fi
touch .gitignore
grep -qxF '.env.infra' .gitignore || printf '.env.infra\n' >> .gitignore
note "đủ công cụ; .env.infra đã nằm trong .gitignore"
pause

# ── 2 ────────────────────────────────────────────────────────────────────
stage "GitHub: repo private + Environments"
if [[ ! -d .git ]]; then
  confirm "Thư mục chưa là git repo. Chạy git init (nhánh main)?" && git init -b main >/dev/null
fi
if ! git remote get-url origin >/dev/null 2>&1; then
  ask GH_REPO_NAME "Tên repo GitHub sẽ tạo (vd ecommerce):"
  write_env GH_REPO_NAME "$GH_REPO_NAME"
  if confirm "Tạo repo PRIVATE '$GH_REPO_NAME' trên GitHub và gắn làm origin?"; then
    gh repo create "$GH_REPO_NAME" --private --source . --remote origin
  else
    warn "chưa có remote: các bước ghi secret phía sau sẽ thất bại"
  fi
else
  note "đã có origin: $(git remote get-url origin)"
fi
local env
for env in staging production; do
  if gh api -X PUT "repos/{owner}/{repo}/environments/$env" >/dev/null 2>&1; then
    printf '  %s✓%s environment %s\n' "$GREEN" "$RESET" "$env"
  else
    SKIPPED+=("tạo environment $env (Settings → Environments → New environment)")
    warn "không tạo được environment $env"
  fi
done
pause

# ── 3 ────────────────────────────────────────────────────────────────────
stage "VPS: SSH key cho GitHub Actions deploy"
say "Cần một user trên VPS mà bạn SSH vào được ngay bây giờ (bằng mật khẩu hoặc key của bạn)."
note "Nếu VPS chỉ có root: SSH vào bằng root, chạy 'adduser deploy', rồi dùng user deploy."
ask DEPLOY_HOST "IP hoặc hostname của VPS:"
write_env DEPLOY_HOST "$DEPLOY_HOST"
ask DEPLOY_USER "User deploy trên VPS:"
write_env DEPLOY_USER "$DEPLOY_USER"
if [[ ! -f "$DEPLOY_KEY" ]]; then
  mkdir -p "$(dirname "$DEPLOY_KEY")"
  ssh-keygen -t ed25519 -N "" -C "github-actions-deploy" -f "$DEPLOY_KEY" >/dev/null
  printf '  %s✓%s tạo key %s\n' "$GREEN" "$RESET" "$DEPLOY_KEY"
else
  note "dùng lại key có sẵn: $DEPLOY_KEY"
fi
if confirm "SSH vào $DEPLOY_USER@$DEPLOY_HOST để thêm public key vào authorized_keys?"; then
  ssh "$DEPLOY_USER@$DEPLOY_HOST" "$ADD_KEY_REMOTE" < "$DEPLOY_KEY.pub" \
    || warn "SSH thất bại; kiểm tra user/host rồi chạy lại"
fi
if ssh -i "$DEPLOY_KEY" -o BatchMode=yes -o ConnectTimeout=10 "$DEPLOY_USER@$DEPLOY_HOST" true 2>/dev/null; then
  printf '  %s✓%s đăng nhập bằng deploy key thành công\n' "$GREEN" "$RESET"
else
  warn "chưa SSH được bằng deploy key; kiểm tra lại rồi chạy lại bước này"
fi
set_secret DEPLOY_SSH_KEY "$(cat "$DEPLOY_KEY")"
set_var DEPLOY_HOST "$DEPLOY_HOST"
set_var DEPLOY_USER "$DEPLOY_USER"
set_var DEPLOY_KNOWN_HOSTS "$(ssh-keyscan -H "$DEPLOY_HOST" 2>/dev/null)"
pause

# ── 4 ────────────────────────────────────────────────────────────────────
stage "Cloudflare DNS: trỏ tên miền về VPS"
ask PROD_DOMAIN "Tên miền production (vd shop.vn):"
write_env PROD_DOMAIN "$PROD_DOMAIN"
ask STAGING_DOMAIN "Tên miền staging (vd staging.shop.vn):"
write_env STAGING_DOMAIN "$STAGING_DOMAIN"
ask VPS_IP "IPv4 của VPS:"
write_env VPS_IP "$VPS_IP"
open_url "https://dash.cloudflare.com/"
step "Chọn tên miền → DNS → Records → Add record."
step "Type A, Name: phần tên của $PROD_DOMAIN (@ nếu là tên miền gốc), IPv4: $VPS_IP."
step "Proxy status: DNS only (mây xám) để Caddy tự lấy chứng chỉ HTTPS. Save."
step "Lặp lại với $STAGING_DOMAIN."
pause "Tạo xong 2 bản ghi thì Enter"
set_env_var production PUBLIC_DOMAIN "$PROD_DOMAIN"
set_env_var staging PUBLIC_DOMAIN "$STAGING_DOMAIN"

# ── 5 ────────────────────────────────────────────────────────────────────
stage "Cloudflare R2: tạo bucket"
open_url "$R2_DASH"
note "Lần đầu dùng R2, Cloudflare yêu cầu bật R2 và thêm phương thức thanh toán (có hạn mức miễn phí)."
step "Create bucket, tạo đủ 5 bucket (Location: Automatic):"
say "    ecommerce-prod-public      ecommerce-prod-private"
say "    ecommerce-staging-public   ecommerce-staging-private"
say "    ecommerce-backups"
pause "Tạo xong 5 bucket thì Enter"
step "Copy Account ID (hiện ở trang R2 Overview hoặc thanh bên phải của trang tổng quan tài khoản)."
ask R2_ACCOUNT_ID "Account ID:"
write_env R2_ACCOUNT_ID "$R2_ACCOUNT_ID"
set_var R2_ACCOUNT_ID "$R2_ACCOUNT_ID"
set_env_var production R2_PUBLIC_BUCKET "ecommerce-prod-public"
set_env_var production R2_PRIVATE_BUCKET "ecommerce-prod-private"
set_env_var staging R2_PUBLIC_BUCKET "ecommerce-staging-public"
set_env_var staging R2_PRIVATE_BUCKET "ecommerce-staging-private"

# ── 6 ────────────────────────────────────────────────────────────────────
stage "Cloudflare R2: tên miền công khai cho ảnh"
say "Chỉ 2 bucket *-public được mở công khai. Bucket private và backups giữ nguyên."
note "Không dùng URL r2.dev cho production: nó bị giới hạn tốc độ."
step "Mở ecommerce-prod-public → Settings → Custom Domains → Connect Domain."
step "Nhập vd img.$PROD_DOMAIN → Connect (Cloudflare tự tạo bản ghi DNS)."
step "Làm tương tự cho ecommerce-staging-public, vd img.$STAGING_DOMAIN."
pause "Kết nối xong thì Enter"
ask R2_PUBLIC_URL_PROD "URL công khai của ecommerce-prod-public (vd https://img.$PROD_DOMAIN):"
write_env R2_PUBLIC_URL_PROD "$R2_PUBLIC_URL_PROD"
ask R2_PUBLIC_URL_STAGING "URL công khai của ecommerce-staging-public:"
write_env R2_PUBLIC_URL_STAGING "$R2_PUBLIC_URL_STAGING"
set_env_var production R2_PUBLIC_URL "$R2_PUBLIC_URL_PROD"
set_env_var staging R2_PUBLIC_URL "$R2_PUBLIC_URL_STAGING"

# ── 7, 8, 9: một R2 token cho mỗi phạm vi, quyền tối thiểu ───────────────
local scope buckets
for scope in staging production backups; do
  case $scope in
    staging)    buckets="ecommerce-staging-public, ecommerce-staging-private" ;;
    production) buckets="ecommerce-prod-public, ecommerce-prod-private" ;;
    backups)    buckets="ecommerce-backups" ;;
  esac
  stage "Cloudflare R2: API token cho $scope"
  open_url "$R2_DASH"
  step "Account Details → API Tokens → Manage → Create Account API token."
  step "Token name: ecommerce-$scope. Permissions: Object Read & Write."
  step "Specify bucket(s): chỉ chọn $buckets."
  step "Create, rồi copy Access Key ID và Secret Access Key (secret chỉ hiện một lần)."
  ask_secret R2_KEY_ID "Access Key ID:"
  ask_secret R2_KEY_SECRET "Secret Access Key:"
  if [[ $scope == backups ]]; then
    set_env_secret production BACKUP_R2_ACCESS_KEY_ID "$R2_KEY_ID"
    set_env_secret production BACKUP_R2_SECRET_ACCESS_KEY "$R2_KEY_SECRET"
    set_env_var production BACKUP_R2_BUCKET "ecommerce-backups"
  else
    set_env_secret "$scope" R2_ACCESS_KEY_ID "$R2_KEY_ID"
    set_env_secret "$scope" R2_SECRET_ACCESS_KEY "$R2_KEY_SECRET"
  fi
  unset R2_KEY_ID R2_KEY_SECRET
  pause
done

# ── 10 ───────────────────────────────────────────────────────────────────
stage "Sentry: tạo project api và web"
open_url "https://sentry.io/"
step "Đăng nhập hoặc đăng ký (gói Developer miễn phí). Tạo organization nếu chưa có."
step "Projects → Create Project → platform Express → tên ecommerce-api."
step "Projects → Create Project → platform Nuxt → tên ecommerce-web."
step "Organization slug là phần tên tổ chức trên URL, vd <slug>.sentry.io."
ask SENTRY_ORG "Organization slug:"
write_env SENTRY_ORG "$SENTRY_ORG"
step "Settings → Projects → ecommerce-api → Client Keys (DSN) → copy DSN."
ask SENTRY_DSN_API "DSN của ecommerce-api:"
write_env SENTRY_DSN_API "$SENTRY_DSN_API"
step "Làm tương tự với ecommerce-web."
ask SENTRY_DSN_WEB "DSN của ecommerce-web:"
write_env SENTRY_DSN_WEB "$SENTRY_DSN_WEB"
set_var SENTRY_ORG "$SENTRY_ORG"
set_var SENTRY_PROJECT_API "ecommerce-api"
set_var SENTRY_PROJECT_WEB "ecommerce-web"
set_var SENTRY_DSN_API "$SENTRY_DSN_API"
set_var SENTRY_DSN_WEB "$SENTRY_DSN_WEB"

# ── 11 ───────────────────────────────────────────────────────────────────
stage "Sentry: token để CI upload source map"
open_url "https://sentry.io/settings/"
step "Settings → Developer Settings → Organization Tokens → Create New Token."
step "Đặt tên github-actions → Create, rồi copy token (chỉ hiện một lần)."
ask_secret SENTRY_AUTH_TOKEN "Organization token:"
set_secret SENTRY_AUTH_TOKEN "$SENTRY_AUTH_TOKEN"
unset SENTRY_AUTH_TOKEN
pause

# ── 12 ───────────────────────────────────────────────────────────────────
stage "Sinh secret ngẫu nhiên: mật khẩu DB và JWT"
say "Tạo POSTGRES_PASSWORD, JWT_CUSTOMER_SECRET, JWT_STAFF_SECRET cho từng environment."
warn "Chạy lại bước này là XOAY VÒNG secret: đổi POSTGRES_PASSWORD sau khi DB đã tạo sẽ làm app không kết nối được DB; đổi JWT sẽ đăng xuất mọi người."
for env in staging production; do
  if confirm "Sinh mới secret cho environment $env?"; then
    set_env_secret "$env" POSTGRES_PASSWORD "$(openssl rand -hex 24)"
    set_env_secret "$env" JWT_CUSTOMER_SECRET "$(openssl rand -base64 48 | tr -d '\n')"
    set_env_secret "$env" JWT_STAFF_SECRET "$(openssl rand -base64 48 | tr -d '\n')"
  else
    note "giữ nguyên secret của $env"
  fi
done
pause

# ── 13 ───────────────────────────────────────────────────────────────────
stage "Khóa mã hóa bản sao lưu (age)"
if ! command -v age-keygen >/dev/null 2>&1; then
  SKIPPED+=("khóa backup: cài age (winget install FiloSottile.age) rồi chạy lại wizard")
  warn "chưa có age-keygen, bỏ qua bước này"
elif confirm "Tạo cặp khóa backup mới? (chỉ làm một lần, trừ khi muốn đổi khóa)"; then
  local keyfile recipient
  keyfile=$(mktemp)
  age-keygen -o "$keyfile" 2>/dev/null
  recipient=$(age-keygen -y "$keyfile")
  say "KHÓA BÍ MẬT bên dưới là thứ DUY NHẤT giải mã được backup. Mất nó là mất backup."
  step "Lưu toàn bộ nội dung bên dưới vào trình quản lý mật khẩu (Bitwarden, 1Password...)."
  printf '\n%s\n\n' "$(cat "$keyfile")"
  until confirm "Đã lưu khóa bí mật an toàn chưa?"; do :; done
  rm -f "$keyfile"
  set_env_var production BACKUP_AGE_RECIPIENT "$recipient"
  note "khóa bí mật đã xóa khỏi máy; chỉ còn public key trên GitHub"
fi
pause

finish
}

run_wizard "$@"; exit
